//! End-to-end test on synthetic mock clips.
//!
//! Runs only when both environment variables are set, because it needs a
//! real speech model and recogniser:
//!   LEC_TRIM_TEST_MODEL     path to ggml-base.en.bin
//!   LEC_TRIM_TEST_WHISPER   path to whisper-cli
//! Mock clips are generated by tools/make_mock_clips.py, which needs
//! ffmpeg with the flite speech synthesiser on PATH.
use std::path::PathBuf;
use std::process::Command;

#[test]
fn end_to_end_mock_clips() {
    let (Ok(model), Ok(whisper)) = (
        std::env::var("LEC_TRIM_TEST_MODEL"),
        std::env::var("LEC_TRIM_TEST_WHISPER"),
    ) else {
        eprintln!("skipping: LEC_TRIM_TEST_MODEL / LEC_TRIM_TEST_WHISPER not set");
        return;
    };
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let work = std::env::temp_dir().join(format!("lec-trim-it-{}", std::process::id()));
    std::fs::create_dir_all(&work).unwrap();
    let gen = Command::new("python3")
        .arg(root.join("tools").join("make_mock_clips.py"))
        .arg(&work)
        .status()
        .unwrap();
    assert!(gen.success(), "mock clip generation failed");

    let run = Command::new(env!("CARGO_BIN_EXE_lec-trim"))
        .arg(&work)
        .arg("--model").arg(&model)
        .arg("--whisper-cli").arg(&whisper)
        .output()
        .unwrap();
    assert!(
        run.status.success(),
        "lec-trim failed: {}",
        String::from_utf8_lossy(&run.stderr)
    );
    let out = work.join("stitched_lecture_v01.mp4");
    assert!(out.exists(), "expected versioned output v01");
    let dur_out = Command::new("ffprobe")
        .args(["-v", "quiet", "-show_entries", "format=duration", "-of", "csv=p=0"])
        .arg(&out)
        .output()
        .unwrap();
    let duration: f64 = String::from_utf8_lossy(&dur_out.stdout).trim().parse().unwrap();
    // Ground truth kept total for the three generated clips is about
    // 23 s; allow 0.5 s of cut error per clip plus part-boundary slack.
    assert!(
        (21.0..26.5).contains(&duration),
        "stitched duration {duration} s outside the expected range"
    );
    let _ = std::fs::remove_dir_all(&work);
}
